('5a4e0000-0000-4000-8000-000000010122', 'selim-dogan', 'Trabzon merkezli lisanslı drone pilotuyum. 7 yıldır konser ve festival çekimleri yapıyorum; uçuş izinlerini ben alırım, 4K video ve yüksek çözünürlüklü fotoğraf teslim ederim. Kurgu ve renk dahil paketlerim var.', 'Trabzon', 'drone-pilotu', '{}'::jsonb, '{"service_region": "Şehir dışına çıkar", "experience_label": "7 yıl · 133+ etkinlik", "calisma_sekli": "Freelance", "quick": {"drone_tipi": ["FPV drone", "Mini drone", "Sinema drone"], "lokasyon_tipi": ["Açık alan", "Kentsel"], "teslim_bicimi": "Fotoğraf", "teslim_suresi": "1 hafta"}, "logistics": {"kurgu_dahil": true, "kendi_ekipmani": true}, "modules": {"ekipman": {"items": ["DJI Mavic 3 Pro", "DJI Avata 2 (FPV)", "Yedek batarya x6", "ND filtre seti"], "venue_requirements": "Sahne yakınında 2 adet 16A priz, kurulum için 60 dk."}, "teknik_teslimat": {"delivery": {"Teslim süresi": "1 hafta", "Format": "JPEG + RAW", "Yedekleme": "Çift kart + bulut"}}, "uzmanlik_alanlari": {"areas": ["Kurumsal Tesis Çekimi", "Drone Fotoğrafçısı", "Spor / Aksiyon Çekimi", "FPV Drone Pilotu"]}, "calisma_parametreleri": {"params": {"Minimum süre": "Tam gün", "Şehir dışı": "Türkiye geneli, ulaşım dahil", "Ödeme": "%30 kapora, kalan etkinlik günü"}, "notes": "Hafta sonu ve resmi tatil için önceden rezervasyon önerilir."}}, "etkinlik_turleri": ["launch", "wedding", "other", "corporate", "concert"]}'::jsonb, 'approved', pg_temp.t(7430.07), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(218.76), pg_temp.t(7437.59)),
('5a4e0000-0000-4000-8000-000000020001', 'ajans-nova', 'Nova Etkinlik, 2014''ten beri İstanbul''da düğün, nişan ve kurumsal etkinlik organizasyonu yapan tam kapsamlı bir ajanstır. Konsept tasarımı, tedarikçi yönetimi ve etkinlik günü operasyonunu tek ekipten yürütür; 60''ın üzerinde düzenli freelance iş ortağıyla çalışır.', 'İstanbul', 'organizasyon', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "6 yıl · 360+ etkinlik", "etkinlik_turleri": ["launch", "wedding", "corporate", "birthday", "conference", "engagement"]}'::jsonb, 'approved', pg_temp.t(5310.75), NULL, NULL, NULL, true, 'agency', pg_temp.t(-864.00), pg_temp.t(8.97), pg_temp.t(5342.69)),
('5a4e0000-0000-4000-8000-000000020002', 'ajans-lumen', 'Lumen Prodüksiyon konser, konferans ve lansmanlarda ses, ışık, LED ekran ve canlı yayın altyapısını kurar. 2.000 kişiye kadar sahne çözümleri, çok kameralı reji ve hibrit yayın hizmetini kendi ekipmanıyla sunar.', 'İstanbul', 'ses-isik', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "6 yıl · 360+ etkinlik", "etkinlik_turleri": ["launch", "engagement", "corporate", "conference", "wedding", "fair", "congress"]}'::jsonb, 'approved', pg_temp.t(5117.81), NULL, NULL, NULL, true, 'plus', pg_temp.t(-3960.00), pg_temp.t(26.44), pg_temp.t(5181.47)),
('5a4e0000-0000-4000-8000-000000020003', 'ajans-atlas', 'Ankara merkezli Atlas Organizasyon, kamu ve özel sektör için kongre, bayi toplantısı ve protokol etkinlikleri düzenler. Kayıt sistemi, simultane çeviri ve sahne prodüksiyonu dahil anahtar teslim çözüm sunar.', 'Ankara', 'organizasyon', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "8 yıl · 480+ etkinlik", "etkinlik_turleri": ["corporate", "birthday", "fair", "congress"]}'::jsonb, 'approved', pg_temp.t(5439.19), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(26.55), pg_temp.t(5481.34)),
('5a4e0000-0000-4000-8000-000000020004', 'ajans-kuzey-yildizi', 'İzmir ve Ege kıyılarında butik düğün ve kına organizasyonları. Kuzey Yıldızı Events, Çeşme, Alaçatı ve Urla''daki mekan ağıyla açık hava davetleri planlar; dekorasyon ve çiçek tasarımı ekibi kendisine aittir.', 'İzmir', 'organizasyon', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "6 yıl · 360+ etkinlik", "etkinlik_turleri": ["wedding", "henna", "baby_shower", "launch"]}'::jsonb, 'approved', pg_temp.t(7545.31), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(144.48), pg_temp.t(7566.14)),
('5a4e0000-0000-4000-8000-000000020005', 'ajans-mavi-sahne', 'Mavi Sahne, sahne sanatçıları temsil eden bir müzik ve performans ajansıdır. Orkestra, DJ, dans ve akrobasi ekipleriyle düğün, gala ve festival programlarına sanatçı sağlar; ses ve ışık ortaklarıyla paket teklif verir.', 'İstanbul', 'muzisyen', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "10 yıl · 600+ etkinlik", "etkinlik_turleri": ["wedding", "corporate", "birthday", "engagement", "launch", "concert", "gala"]}'::jsonb, 'approved', pg_temp.t(7929.87), NULL, NULL, NULL, true, 'agency', pg_temp.t(-3456.00), pg_temp.t(32.41), pg_temp.t(7976.45)),
('5a4e0000-0000-4000-8000-000000020006', 'ajans-arti-bir', 'Artı Bir Ajans sunucu, konuşmacı ve komedyen portföyüyle kurumsal etkinliklerin sahne akışını kurar. Bayi toplantısı, ödül töreni ve lansmanlar için iki dilli sunucu ve ara performans sağlar.', 'İstanbul', 'sunucu', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "8 yıl · 480+ etkinlik", "etkinlik_turleri": ["corporate", "conference", "launch", "other"]}'::jsonb, 'approved', pg_temp.t(10599.36), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(27.76), pg_temp.t(10651.30)),
('5a4e0000-0000-4000-8000-000000020007', 'ajans-ritim', 'Antalya merkezli Ritim Müzik Ajansı otel ve beach club etkinliklerine DJ, canlı müzik ve dans ekipleri sağlar. Sezonluk rezidans programları ve düğün paketleriyle Akdeniz bölgesinde çalışır.', 'Antalya', 'dj', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "14 yıl · 840+ etkinlik", "etkinlik_turleri": ["birthday", "wedding", "engagement", "concert", "gala", "launch"]}'::jsonb, 'approved', pg_temp.t(9403.59), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(117.60), pg_temp.t(9412.34)),
('5a4e0000-0000-4000-8000-000000020008', 'ajans-vizyon-cast', 'Vizyon Cast Ajansı reklam, katalog ve etkinlikler için model, oyuncu ve host kadrosu sağlar. 200''ü aşkın portföy, seçme (casting) organizasyonu ve set günü koordinasyonu hizmetleriyle marka ve prodüksiyon şirketleriyle çalışır.', 'İstanbul', 'model', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "12 yıl · 720+ etkinlik", "etkinlik_turleri": ["gala", "corporate", "launch", "henna", "fair"]}'::jsonb, 'approved', pg_temp.t(4718.89), NULL, NULL, NULL, true, 'plus', pg_temp.t(-6192.00), pg_temp.t(86.62), pg_temp.t(4770.60)),
('5a4e0000-0000-4000-8000-000000020009', 'ajans-pusula', 'Bursa merkezli Pusula Etkinlik sanayi kuruluşlarının bayi toplantısı, fabrika açılışı ve fuar katılımlarını planlar. Saha koordinasyon ekibi, hostes kadrosu ve teknik tedarikçi ağıyla Marmara bölgesinde hizmet verir.', 'Bursa', 'etkinlik-koordinatoru', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "10 yıl · 600+ etkinlik", "etkinlik_turleri": ["conference", "corporate", "gala", "launch"]}'::jsonb, 'approved', pg_temp.t(9219.90), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(34.11), pg_temp.t(9266.00)),
('5a4e0000-0000-4000-8000-000000020010', 'ajans-ekim', 'Ekim Kreatif, lansman ve marka etkinliklerinin sosyal medya katmanını yönetir: içerik üreticisi eşleştirme, etkinlik günü çekim ekibi, canlı yayın ve aynı gün kurgu. Veriye dayalı raporlama sunar.', 'İstanbul', 'influencer', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "14 yıl · 840+ etkinlik", "etkinlik_turleri": ["wedding", "launch", "corporate", "engagement", "fair", "birthday"]}'::jsonb, 'approved', pg_temp.t(11597.53), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(61.60), pg_temp.t(11640.12)),
('5a4e0000-0000-4000-8000-000000020011', 'ajans-beyaz-guvercin', 'Gaziantep ve Güneydoğu''da düğün, kına ve sünnet organizasyonları. Beyaz Güvercin, yöresel müzik ekipleri, geleneksel kına programı ve çocuk eğlencesi dahil aile etkinliklerinde 12 yıllık deneyime sahiptir.', 'Gaziantep', 'organizasyon', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "10 yıl · 600+ etkinlik", "etkinlik_turleri": ["henna", "wedding", "corporate", "launch", "birthday", "engagement"]}'::jsonb, 'approved', pg_temp.t(2401.44), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(55.00), pg_temp.t(2456.08)),
('5a4e0000-0000-4000-8000-000000020012', 'ajans-zirve', 'Zirve Teknik Prodüksiyon kongre ve konferanslara simultane çeviri kabini, ses-ışık, kayıt ve canlı yayın altyapısı sağlar. Ankara''daki kongre merkezlerinde düzenli tedarikçidir; 1.500 kişiye kadar salon kurulumu yapar.', 'Ankara', 'ses-isik', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "6 yıl · 360+ etkinlik", "etkinlik_turleri": ["corporate", "launch", "concert", "conference", "wedding", "congress", "gala"]}'::jsonb, 'approved', pg_temp.t(8030.48), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(227.66), pg_temp.t(8058.42)),
